    private final class Cursor {
        final byte[] data;
        int p;
        final int fs;

        Cursor(byte[] data, int p, int fs) {
            this.data = data;
            this.p = p;
            this.fs = fs;
        }

        long vi() {
            if (p >= data.length) {
                throw err();
            }
            int b = data[p++] & 255;
            int width = 1 << (b >>> 6);
            if (width > data.length - p) {
                throw err();
            }
            long v = b & 0x3fL;
            for (int i = 1; i < width; i++) {
                v = (v << 8) | (data[p++] & 255L);
            }
            return v;
        }

        int one() {
            if (p >= data.length) {
                throw err();
            }
            return data[p++] & 255;
        }

        byte[] take(long n) {
            if (n < 0 || n > data.length - p) {
                throw err();
            }
            int k = (int) n;
            byte[] out = Arrays.copyOfRange(data, p, p + k);
            p += k;
            return out;
        }

        byte[] rest() {
            return take(data.length - p);
        }

        WireException err() {
            return new WireException(FRAME_ENCODING_ERROR, fs);
        }
